import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel source for matrix multiplication (naive GEMM)
matmul_kernel_cuda_src = """
#include <torch/extension.h>
#include <cuda_runtime.h>

constexpr int BLOCK_SIZE = 256;

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int N) {
    // Each thread computes one element of the output matrix C.
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < M * N) {
        int i = idx / N;
        int j = idx % N;
        float sum = 0.0f;
        for (int k = 0; k < N; ++k) {
            sum += A[i * N + k] * B[k * N + j];
        }
        C[idx] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    auto sizeA = A.numel();
    auto out = torch::zeros_like(A);

    const int block_size = 256;
    const int num_blocks = (sizeA + block_size - 1) / block_size;

    matmul_kernel<<<num_blocks, block_size>>>(A.data_ptr<float>(), B.data_ptr<float()>, out.data_ptr<float()>, A.size(0), A.size(1));

    return out;
}
"""

